SELECT id, order_no, user_id, address_id, remark, status, total_cent, created_at, updated_at
FROM shop_order
WHERE id = #{id}

SELECT id, order_no, user_id, address_id, remark, status, total_cent, created_at, updated_at
FROM shop_order
WHERE user_id = #{userId}

  AND status = #{status}

ORDER BY created_at DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(1)
FROM shop_order
WHERE user_id = #{userId}

  AND status = #{status}
